content:
:root {
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --radius: 8px;
  --shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --primary-color: #3b82f6;
    --primary-hover: #60a5fa;
    --danger-color: #f87171;
    --danger-hover: #ef4444;
    --shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.4), 0 1px 2px 0 rgba(0, 0, 0, 0.2);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4), 0 4px 6px -2px rgba(0, 0, 0, 0.2);
  }
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  -webkit-font-smoothing: antialiased;
}

.kanban-app {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
  box-sizing: border-box;
}

.kanban-header {
  margin-bottom: 24px;
  background: var(--card-bg);
  padding: 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.kanban-header h1 {
  margin: 0 0 16px 0;
  font-size: 1.5rem;
  color: var(--text-main);
}

.add-task-form {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.form-input {
  flex: 1;
  min-width: 200px;
  padding: 10px 14px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  font-size: 0.95rem;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  background-color: var(--card-bg);
  color: var(--text-main);
}

.form-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.4);
}

textarea.form-input {
  resize: vertical;
  min-height: 40px;
}

.btn {
  padding: 8px 16px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  background-color: var(--card-bg);
  color: var(--text-main);
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s, transform 0.1s, box-shadow 0.2s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.btn:hover {
  background-color: var(--border-color);
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.4);
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: var(--primary-color);
  border-color: var(--primary-color);
  color: #fff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
  border-color: var(--primary-hover);
}

.kanban-board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  align-items: start;
}

.kanban-column {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  min-height: 500px;
}

.kanban-column-header {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.kanban-task-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
  min-height: 100px;
}

.task-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 14px;
  box-shadow: var(--shadow);
  cursor: grab;
  transition: box-shadow 0.2s, transform 0.2s;
  border: 1px solid var(--border-color);
  position: relative;
}

.task-card:active {
  cursor: grabbing;
}

.task-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.task-title {
  font-weight: 600;
  font-size: 1rem;
  margin-bottom: 6px;
  color: var(--text-main);
  word-break: break-word;
}

.task-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 12px;
  word-break: break-word;
  white-space: pre-wrap;
}

.task-actions {
  display: flex;
  justify-content: flex-end;
  gap: 6px;
  border-top: 1px solid var(--border-color);
  padding-top: 8px;
  margin-top: 8px;
}

.task-actions .btn {
  padding: 4px 10px;
  font-size: 0.8rem;
}

@media (max-width: 1024px) {
  .kanban-board {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .kanban-app {
    padding: 12px;
  }

  .kanban-board {
    grid-template-columns: 1fr;
  }
}

export type TaskStatus = 'todo' | 'in_progress' | 'review' | 'done' | string;

export type Priority = 'low' | 'medium' | 'high';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority?: Priority;
  dueDate?: string;
  order?: number;
}

export interface ColumnConfig {
  id: TaskStatus;
  title: string;
}

import { FC, useState } from 'react';
import { Task, TaskStatus } from './types';

interface TaskCardProps {
  task: Task;
  onDragStart: (e: React.DragEvent, id: string) => void;
  onDelete: (id: string) => void;
  onMove: (id: string, status: TaskStatus) => void;
}

export const TaskCard: FC<TaskCardProps> = ({
  task,
  onDragStart,
  onDelete,
  onMove,
}) => {
  const [isDragging, setIsDragging] = useState(false);

  const statuses: { id: TaskStatus; label: string }[] = [
    { id: 'todo', label: '未着手' },
    { id: 'in_progress', label: '作業中' },
    { id: 'done', label: '完了' },
  ];

  const handleDelete = () => {
    if (window.confirm('このタスクを削除しますか？')) {
      onDelete(task.id);
    }
  };

  return (
    <div
      className="task-card"
      draggable
      onDragStart={(e) => {
        setIsDragging(true);
        onDragStart(e, task.id);
      }}
      onDragEnd={() => setIsDragging(false)}
      style={{ opacity: isDragging ? 0.4 : 1 }}
    >
      <div className="task-title">{task.title}</div>
      {task.description && <div className="task-desc">{task.description}</div>}
      <div className="task-actions">
        <select
          className="form-input"
          style={{ padding: '4px 8px', fontSize: '0.8rem', height: 'auto', flex: 1 }}
          value={task.status}
          onChange={(e) => onMove(task.id, e.target.value as TaskStatus)}
        >
          {statuses.map((s) => (
            <option key={s.id} value={s.id}>
              {s.label}
            </option>
          ))}
        </select>
        <button
          className="btn"
          style={{ color: 'var(--danger-color)', borderColor: 'var(--danger-color)' }}
          onClick={handleDelete}
        >
          削除
        </button>
      </div>
    </div>
  );
};

import { FC, useState } from 'react';
import { ColumnConfig, Task, TaskStatus } from './types';
import { TaskCard } from './TaskCard';

interface ColumnProps {
  column: ColumnConfig;
  tasks?: Task[];
  onDragOver: (e: React.DragEvent) => void;
  onDrop: (e: React.DragEvent, status: TaskStatus) => void;
  onDragStart: (e: React.DragEvent, id: string) => void;
  onDeleteTask: (id: string) => void;
  onMoveTask: (id: string, status: TaskStatus) => void;
}

export const Column: FC<ColumnProps> = ({
  column,
  tasks = [],
  onDragOver,
  onDrop,
  onDragStart,
  onDeleteTask,
  onMoveTask,
}) => {
  const [isDragOver, setIsDragOver] = useState(false);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    onDragOver(e);
    setIsDragOver(true);
  };

  const handleDragLeave = () => {
    setIsDragOver(false);
  };

  const handleDrop = (e: React.DragEvent, status: TaskStatus) => {
    setIsDragOver(false);
    onDrop(e, status);
  };

  return (
    <div
      className="kanban-column"
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={(e) => handleDrop(e, column.id)}
      style={{
        backgroundColor: isDragOver ? 'var(--border-color)' : 'var(--card-bg)',
        transition: 'background-color 0.2s',
      }}
    >
      <div className="kanban-column-header">
        <span>{column.title}</span>
        <span style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>
          {tasks.length}
        </span>
      </div>
      <div className="kanban-task-list">
        {tasks.length === 0 ? (
          <div
            style={{
              padding: '24px 12px',
              textAlign: 'center',
              color: 'var(--text-muted)',
              fontSize: '0.9rem',
              border: '2px dashed var(--border-color)',
              borderRadius: 'var(--radius)',
              margin: 'auto 0',
            }}
          >
            タスクがありません
          </div>
        ) : (
          tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onDragStart={onDragStart}
              onDelete={onDeleteTask}
              onMove={onMoveTask}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default Column;

import { useState, useEffect } from 'react';
import { Task, ColumnConfig, TaskStatus } from './types';
import { Column } from './Column';

const initialTasks: Task[] = [
  {
    id: '1',
    title: 'プロジェクト計画の作成',
    description: 'マイルストーンとスケジュールを定義する',
    status: 'todo',
  },
  {
    id: '2',
    title: '要件定義書のレビュー',
    description: 'ステークホルダーからのフィードバックを反映',
    status: 'todo',
  },
  {
    id: '3',
    title: 'UI/UXデザイン設計',
    description: 'ワイヤーフレームとモックアップを作成',
    status: 'in_progress',
  },
  {
    id: '4',
    title: 'API設計',
    description: 'エンドポイントの仕様をドキュメント化',
    status: 'in_progress',
  },
  {
    id: '5',
    title: 'リポジトリの初期化',
    description: 'Gitリポジトリを作成し、基本構成をインポート',
    status: 'done',
  },
  {
    id: '6',
    title: 'キックオフミーティング',
    description: 'チームメンバー全員で目標を共有',
    status: 'done',
  },
];

const columns: ColumnConfig[] = [
  { id: 'todo', title: '未着手' },
  { id: 'in_progress', title: '作業中' },
  { id: 'done', title: '完了' },
];

export function App() {
  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('kanban_tasks');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error('Failed to parse tasks from localStorage', e);
      }
    }
    return initialTasks;
  });

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [status, setStatus] = useState<TaskStatus>('todo');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    localStorage.setItem('kanban_tasks', JSON.stringify(tasks));
  }, [tasks]);

  const handleAddTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;

    const newTask: Task = {
      id:
        typeof crypto !== 'undefined' && crypto.randomUUID
          ? crypto.randomUUID()
          : Date.now().toString() + Math.random().toString(36).substring(2, 9),
      title: title.trim(),
      description: description.trim(),
      status,
    };

    setTasks((prev) => [newTask, ...prev]);
    setTitle('');
    setDescription('');
    setStatus('todo');
  };

  const handleDeleteTask = (id: string) => {
    setTasks((prev) => prev.filter((task) => task.id !== id));
  };

  const handleMoveTask = (id: string, newStatus: TaskStatus) => {
    setTasks((prev) =>
      prev.map((task) => (task.id === id ? { ...task, status: newStatus } : task))
    );
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
    e.dataTransfer.setData('text/plain', id);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, newStatus: TaskStatus) => {
    e.preventDefault();
    const id = e.dataTransfer.getData('text/plain');
    if (id) {
      handleMoveTask(id, newStatus);
    }
  };

  const filteredTasks = tasks.filter((task) => {
    const query = searchQuery.toLowerCase();
    return (
      task.title.toLowerCase().includes(query) ||
      task.description.toLowerCase().includes(query)
    );
  });

  return (
    <div className="kanban-app">
      <header className="kanban-header">
        <h1>カンバンボード</h1>
        <div style={{ marginBottom: '16px' }}>
          <input
            type="text"
            className="form-input"
            placeholder="タスクを検索..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={{ width: '100%', boxSizing: 'border-box' }}
          />
        </div>
        <form className="add-task-form" onSubmit={handleAddTask}>
          <input
            type="text"
            className="form-input"
            placeholder="タスクのタイトル"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <input
            type="text"
            className="form-input"
            placeholder="詳細（任意）"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
          <select
            className="form-input"
            style={{ flex: '0 0 150px' }}
            value={status}
            onChange={(e) => setStatus(e.target.value as TaskStatus)}
          >
            {columns.map((col) => (
              <option key={col.id} value={col.id}>
                {col.title}
              </option>
            ))}
          </select>
          <button type="submit" className="btn btn-primary">
            タスク追加
          </button>
        </form>
      </header>

      <main className="kanban-board">
        {columns.map((col) => (
          <Column
            key={col.id}
            column={col}
            tasks={filteredTasks.filter((t) => t.status === col.id)}
            onDragOver={handleDragOver}
            onDrop={handleDrop}
            onDragStart={handleDragStart}
            onDeleteTask={handleDeleteTask}
            onMoveTask={handleMoveTask}
          />
        ))}
      </main>
    </div>
  );
}

export default App;
